public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Determine the minimum length among all strings to bound the search
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            s = "";
        }
        if (s.length() < minLen) {
            minLen = s.length();
        }
    }
    if (minLen == 0) {
        return 0;
    }
    // Use the first non-null string as the source of candidate substrings
    String first = null;
    for (String s : strings) {
        if (s != null) {
            first = s;
            break;
        }
    }
    if (first == null) {
        return 0;
    }
    // Iterate lengths from largest to smallest
    for (int len = minLen; len >= 1; len--) {
        // Use a set to avoid duplicate candidates
        java.util.HashSet<String> seen = new java.util.HashSet<>();
        for (int i = 0; i <= first.length() - len; i++) {
            String candidate = first.substring(i, i + len);
            if (!seen.add(candidate)) {
                continue; // already processed this candidate
            }
            String revCandidate = new StringBuilder(candidate).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (s == null) {
                    s = "";
                }
                if (!(s.contains(candidate) || s.contains(revCandidate))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

