    boolean[] subtreeHasApple = new boolean[n];
    int total = 0;
    java.util.Stack<int[]> stack = new java.util.Stack<>();
    stack.push(new int[]{0, -1, 0});
    while (!stack.isEmpty()) {
        int[] cur = stack.pop();
        int node = cur[0];
        int parent = cur[1];
        int state = cur[2];
        if (state == 0) {
