    int maxCount = 0;
    int totalMasks = 1 << (n - 1); // number of ways to cut between characters
    for (int mask = 0; mask < totalMasks; mask++) {
        java.util.HashSet<String> seen = new java.util.HashSet<>();
        int start = 0;
        boolean valid = true;
        for (int i = 0; i < n - 1; i++) {
