private static void dfs(long curr, int n, List<Integer> result) {
    if (curr > n) {
        return;
    }
    result.add((int) curr);
    for (int d = 0; d <= 9; d++) {
        long next = curr * 10 + d;
        if (next > n) {
            break;
        }
        dfs(next, n, result);
    }
}

